       border: 1px solid var(--border);
       border-radius: 28px;
       background: linear-gradient(145deg, rgba(17, 24, 39, 0.96), rgba(15, 23, 42, 0.9));
       box-shadow: 0 24px 70px rgba(0, 0, 0, 0.48), inset 0 1px 0 rgba(255, 255, 255, 0.06);
       backdrop-filter: blur(18px);
     }

     h1 {
       margin: 0 0 10px;
       font-size: clamp(1.8rem, 5vw, 2.55rem);
       line-height: 1.05;
       letter-spacing: -0.04em;
     }

     .intro {
       margin: 0 0 28px;
       color: var(--muted);
       line-height: 1.6;
     }

     .form-field {
       margin: 0 0 28px;
       padding: 22px;
       border: 1px solid var(--border);
       border-radius: 22px;
       background: rgba(24, 34, 53, 0.72);
     }

     .question {
       display: block;
       margin-bottom: 16px;
       font-size: 1.08rem;
       font-weight: 700;
       letter-spacing: -0.01em;
     }

     .options {
       display: grid;
       gap: 12px;
     }

     .option {
       position: relative;
       display: flex;
       align-items: center;
       gap: 12px;
       min-height: 56px;
       padding: 14px 16px;
       border: 1px solid var(--border);
       border-radius: 16px;
       color: var(--text);
       background: rgba(8, 11, 20, 0.38);
       cursor: pointer;
       transition: border-color 160ms ease, background 160ms ease, transform 160ms ease;
     }

     .option:hover {
       border-color: rgba(167, 139, 250, 0.62);
       background: rgba(139, 92, 246, 0.1);
       transform: translateY(-1px);
     }

     .option input {
       width: 20px;
       height: 20px;
       margin: 0;
       accent-color: var(--accent);
     }

     .option:has(input:checked) {
       border-color: var(--accent-strong);
       background: rgba(139, 92, 246, 0.18);
       box-shadow: 0 0 0 4px var(--ring);
     }

     button {
       width: 100%;
       min-height: 54px;
       border: 0;
       border-radius: 16px;
       color: white;
       font: inherit;
       font-weight: 800;
       letter-spacing: 0.01em;
       background: linear-gradient(135deg, #7c3aed, #2563eb);
       box-shadow: 0 14px 30px rgba(37, 99, 235, 0.26);
       cursor: pointer;
       transition: transform 160ms ease, filter 160ms ease, box-shadow 160ms ease;
     }

     button:hover {
       filter: brightness(1.08);
       transform: translateY(-1px);
       box-shadow: 0 18px 36px rgba(37, 99, 235, 0.32);
     }

     button:focus-visible,
     .option input:focus-visible {
       outline: 3px solid var(--accent-strong);
       outline-offset: 4px;
     }

     .message {
       min-height: 24px;
       margin: 18px 0 0;
       color: var(--accent-strong);
       font-weight: 700;
       text-align: center;
     }

     @media (max-width: 520px) {
       .card {
         padding: 26px;
         border-radius: 24px;
       }
     }
   </style>
 </head>
 <body>
   <main>
     <section class="card" aria-labelledby="form-title">
       <h1 id="form-title">Notification Preferences</h1>
       <p class="intro">Choose the channel that works best for timely updates.</p>

       <form id="notification-form">
         <div class="form-field">
           <span class="question" id="notification-question">How do you prefer to receive notifications?</span>

           <div class="options" role="radiogroup" aria-labelledby="notification-question">
             <label class="option">
               <input type="radio" name="notification" value="Email" required>
               <span>Email</span>
             </label>

             <label class="option">
               <input type="radio" name="notification" value="SMS">
               <span>SMS</span>
             </label>

             <label class="option">
               <input type="radio" name="notification" value="Push Notifications">
               <span>Push Notifications</span>
             </label>
           </div>
         </div>

         <button type="submit">Submit preference</button>
         <p class="message" id="form-message" aria-live="polite"></p>
       </form>
     </section>
   </main>

   <script>
     const form = document.querySelector("#notification-form");
     const message = document.querySelector("#form-message");

     form.addEventListener("submit", (event) => {
       event.preventDefault();

       const selected = new FormData(form).get("notification");
       message.textContent = `Preference saved: ${selected}`;
     });
   </script>
 </body>
 </html>

')
